  assert.equal(s.top(), undefined);
  assert.equal(s.getMin(), undefined);
  assert.equal(s.pop(), undefined);
  s.push(42);
  assert.equal(s.getMin(), 42);
});

/**
 * Min Stack — a stack that knows its minimum in O(1).
 *
 * The trick: a second stack, `mins`, kept exactly in step with
 * `values`. mins[i] = "the minimum of values[0..i]". Pushing computes
 * the new running minimum in O(1); popping both stacks together makes
 * the previous minimum reappear with zero recomputation.
 *
 * All four operations: O(1) time. Space: O(n) extra for `mins`.
 */
export class MinStack {
  constructor() {
    /** @type {number[]} the actual stack contents */
    this.values = [];
    /** @type {number[]} mins[i] = min of values[0..i] */
    this.mins = [];
  }

  /**
   * Add a value on top of the stack.
   * @param {number} value
   * @returns {void}
   */
  push(value) {
    this.values.push(value);
    const currentMin = this.mins.length === 0
      ? value
      : Math.min(value, this.mins[this.mins.length - 1]);
    this.mins.push(currentMin);
  }

  /**
   * Remove and return the top value.
   * @returns {number|undefined} the removed value, or undefined if empty
   */
  pop() {
    this.mins.pop(); // keep the two stacks in step
    return this.values.pop();
  }

  /**
   * Return the top value without removing it.
   * @returns {number|undefined}
   */
  top() {
    return this.values.length === 0
      ? undefined
      : this.values[this.values.length - 1];
  }

  /**
   * Return the smallest value currently in the stack, in O(1).
   * @returns {number|undefined}
   */
  getMin() {
    return this.mins.length === 0
      ? undefined
      : this.mins[this.mins.length - 1];
  }
}

import test from "node:test";
import assert from "node:assert/strict";
import { MinStack } from "./solution.js";

test("classic sequence: push -2, 0, -3", () => {
  const s = new MinStack();
  s.push(-2);
  s.push(0);
  s.push(-3);
  assert.equal(s.getMin(), -3);
  assert.equal(s.pop(), -3); // pop returns the removed value
  assert.equal(s.top(), 0);
  assert.equal(s.getMin(), -2); // old minimum comes back
});

test("duplicate minimums survive a single pop", () => {
  const s = new MinStack();
  s.push(3);
  s.push(1);
  s.push(1);
  assert.equal(s.getMin(), 1);
  s.pop();
  assert.equal(s.getMin(), 1); // the other copy of 1 is still in
  s.pop();
  assert.equal(s.getMin(), 3);
});

test("minimum falls and rises as values come and go", () => {
  const s = new MinStack();
  s.push(5);
  assert.equal(s.getMin(), 5);
  s.push(3);
  s.push(7);
  assert.equal(s.getMin(), 3); // 7 didn't change the min
  assert.equal(s.pop(), 7);
  s.pop(); // removes 3
  assert.equal(s.getMin(), 5);
