test("empty stack returns undefined, then works again", () => {
  const s = new MinStack();
  assert.equal(s.top(), undefined);
  assert.equal(s.getMin(), undefined);
  assert.equal(s.pop(), undefined);
  s.push(42);
  assert.equal(s.getMin(), 42);
});
